/**
 * Bundled basic-strategy data, version 1.
 *
 * Source: original decisions generated by the EV model in ./ev.ts via
 * `npm run generate` (see ./generate.ts). No third-party chart is copied.
 * Verification: tests/strategy.test.ts regenerates the data and checks it is
 * identical to this file, then compares full grids against independently
 * written reference decisions (tests/reference.ts), which were checked against
 * the published rules text of the references below.
 *
 * Rule scope: 1, 2, 4, 6 or 8 decks; S17/H17; US peek or no hole card; double
 * any two / hard 9–11 / hard 10–11; DAS on/off; late surrender on/off; split
 * to 2–4 hands; resplit aces on/off; hit split aces on/off. Every combination
 * has data. Basic strategy is total-dependent: it uses the player's hand total
 * (or pair) and the dealer upcard only; it is not card counting.
 */
import raw from './data/strategy-v1.json';
import { cardValue, type Rank } from './cards';
import { baseKey, PAIR_ROWS, splitKey, UP_COLUMNS, type StrategyData } from './layout';
import type { Rules } from './rules';

const data = raw as StrategyData;

export const STRATEGY_VERSION = data.version;

export const SOURCES = [
  {
    label: 'Wizard of Odds — Basic Strategy Calculator',
    url: 'https://wizardofodds.com/games/blackjack/strategy/calculator/',
  },
  {
    label: 'Wizard of Odds — 4-Deck to 8-Deck Blackjack Strategy',
    url: 'https://wizardofodds.com/games/blackjack/strategy/4-decks/',
  },
  {
    label: 'Wizard of Odds — European Blackjack Strategy',
    url: 'https://wizardofodds.com/games/blackjack/strategy/european/',
  },
  {
    label: 'Wizard of Odds — Single-Deck and Double-Deck Strategy',
    url: 'https://wizardofodds.com/games/blackjack/strategy/1-deck/',
  },
] as const;

function column(up: Rank): number {
  return UP_COLUMNS.indexOf(cardValue(up) as (typeof UP_COLUMNS)[number]);
}

function baseTable(rules: Rules) {
  const t = data.base[baseKey(rules.decks, rules.h17, rules.peek)];
  if (!t) throw new Error(`No strategy data for ${baseKey(rules.decks, rules.h17, rules.peek)}`);
  return t;
}

/** Moves ordered best-first (letters H, S, D, R) for a hard or soft total. */
export function totalRanking(rules: Rules, softness: 'hard' | 'soft', total: number, up: Rank): string {
  const t = baseTable(rules);
  const row = softness === 'hard' ? t.hard[total] : t.soft[total];
  if (!row) throw new Error(`No ${softness} ${total} row`);
  return row[column(up)];
}

/** Moves ordered best-first for an untouched pair when splitting is not considered. */
export function pairRanking(rules: Rules, pair: Rank, up: Rank): string {
  return baseTable(rules).pair[cardValue(pair)][column(up)];
}

/** Moves ordered best-first for a pair, including P (split). */
export function pairRankingWithSplit(rules: Rules, pair: Rank, up: Rank): string {
  const key = splitKey(baseKey(rules.decks, rules.h17, rules.peek), rules);
  const grid = data.splitGrids[data.split[key]];
  if (grid === undefined) throw new Error(`No split data for ${key}`);
  const row = PAIR_ROWS.indexOf(cardValue(pair) as (typeof PAIR_ROWS)[number]);
  const pos = Number(grid[row * UP_COLUMNS.length + column(up)]);
  const others = pairRanking(rules, pair, up);
  return others.slice(0, pos) + 'P' + others.slice(pos);
}
